#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();
    vector<int> run(n, 0);
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (s[i] == ')') {
            if (s[i - 1] == '(') {
                run[i] = (i >= 2 ? run[i - 2] : 0) + 2;
            } else {
                int j = i - run[i - 1] - 1;
                if (j >= 0 && s[j] == '(') run[i] = run[i - 1] + 2 + (j >= 1 ? run[j - 1] : 0);
            }
            best = max(best, run[i]);
        }
    }
    cout << best << "\n";

    return 0;
}

